observation.command:
cd /workspace/deployment && cp docker-compose.dev.yml /tmp/dcdev.bak && python3 - <<'PY' 2>/dev/null || awk '
BEGIN {
  innginx=0
}
/  nginx:$/ { innginx=1 }
innginx && /^\s+- \.\/nginx\/nginx\.conf:\/etc\/nginx\/conf\.d\/default\.conf:ro$/ {
  print "      - ./nginx/default.conf:/etc/nginx/conf.d/default.conf:ro"
  innginx=0
  next
}
{ print }
' docker-compose.dev.yml > /tmp/dcdev.step1 && diff /tmp/dcdev.bak /tmp/dcdev.step1
PY
echo "done"
